{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest structural analogue, KNI-272, showed absolute oral bioavailability of about 55% in adult patients in the fasting state, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, a peptidomimetic HIV protease inhibitor with a similar hydroxyethylamine core, had systemic bioavailability of about 60% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Boceprevir, another peptidomimetic protease inhibitor, had an estimated oral bioavailability of approximately 20%, meeting the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Telaprevir, a peptidomimetic protease inhibitor, is reported to have good oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Remikiren, a peptidomimetic renin inhibitor, had extremely low absolute bioavailability of 0.2%, showing that some peptidomimetics can be very poorly absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alvimopan, a peptidic opioid antagonist, had low oral bioavailability of 6%, but it contains ionizable groups not present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "In children, KNI-272 showed a lower mean absolute bioavailability of 12%, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a peptidomimetic HIV protease inhibitor most closely related to KNI-272, whose adult absolute bioavailability is consistently above 20%, and to other orally bioavailable peptidomimetic protease inhibitors such as indinavir (~60%), boceprevir (~20%), and telaprevir (good). The low-bioavailability analogues (remikiren, alvimopan) are less transferable because they contain additional polar or ionizable groups. Overall, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "The closest analogue KNI-272 shows variable bioavailability (12% in children vs 22-55% in adults).",
    "No data on formulation, dose, or food effects for the query.",
    "Morgan similarities are modest (<0.3), limiting structural transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

